begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(60);
insert into auth.users(id,email) values
 ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','graph-a@example.invalid'),
 ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','graph-b@example.invalid');
insert into public.rundown_versions(id,title,area,summary,stops,published,route_template) select '91111111-1111-4111-8111-111111111111','Synthetic graph route','Synthetic','Not real travel information',stops,true,'{"landing":{"kind":"separate","location":{"latitude":0,"longitude":1,"label":"Synthetic landing"}},"stop_details":[{"source_stop_id":"21111111-1111-4111-8111-111111111111","location":{"latitude":0,"longitude":2},"visit_duration_seconds":300,"time_zone":"UTC"},{"source_stop_id":"21111111-1111-4111-8111-111111111112","location":{"latitude":0,"longitude":3},"visit_duration_seconds":600,"time_zone":"UTC"}],"legs":[{"id":"81111111-1111-4111-8111-111111111111","kind":"landing_to_first","to_stop_id":"21111111-1111-4111-8111-111111111111","transport_mode":"walk","duration_seconds":90},{"id":"81111111-1111-4111-8111-111111111112","kind":"between_stops","from_stop_id":"21111111-1111-4111-8111-111111111111","to_stop_id":"21111111-1111-4111-8111-111111111112","transport_mode":"walk","duration_seconds":180}]}'::jsonb from public.rundown_versions where id='11111111-1111-4111-8111-111111111111';
insert into public.rundown_versions(id,title,area,summary,stops,published,route_template) select '91111111-1111-4111-8111-111111111112','Synthetic graph route','Synthetic','Not real travel information',stops,true,'{"landing":{"kind":"first_stop"},"stop_details":[{"source_stop_id":"21111111-1111-4111-8111-111111111111","location":{"latitude":0,"longitude":2},"visit_duration_seconds":300,"time_zone":"UTC"},{"source_stop_id":"21111111-1111-4111-8111-111111111112","location":{"latitude":0,"longitude":3},"visit_duration_seconds":600,"time_zone":"UTC"}],"legs":[{"id":"81111111-1111-4111-8111-111111111112","kind":"between_stops","from_stop_id":"21111111-1111-4111-8111-111111111111","to_stop_id":"21111111-1111-4111-8111-111111111112","transport_mode":"walk","duration_seconds":180}]}'::jsonb from public.rundown_versions where id='11111111-1111-4111-8111-111111111111';

set local role anon;
select throws_ok($$select public.get_trip_graph(gen_random_uuid())$$,'42501','permission denied for function get_trip_graph','Anonymous graph denied');
select throws_ok($$select public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','unspecified',gen_random_uuid())$$,'42501','permission denied for function create_trip_v3','Anonymous graph command denied');
select throws_ok($$select * from public.trip_stops$$,'42501','permission denied for table trip_stops','Anonymous normalized reads denied');
select is(public.get_rundown_route('91111111-1111-4111-8111-111111111111')->'route_template'->'landing'->>'kind','separate','Published route available without a session');
select throws_ok($$select public.get_rundown_route('99999999-9999-4999-8999-999999999999')$$,'PT404','Published version not found','Unknown route hidden uniformly');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.get_trip_graph(gen_random_uuid())$$,'PT401','Traveller session required','Graph requires a subject');
select throws_ok($$select public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','unspecified',gen_random_uuid())$$,'PT401','Traveller session required','Definer graph command checks subject');
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select set_config('c67.graph_a',public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','departure_origin','51111111-1111-4111-8111-111111111111','{"latitude":0,"longitude":0,"label":"Synthetic origin"}')::text,true);
select set_config('c67.graph_a_id',current_setting('c67.graph_a')::jsonb->>'id',true);
select is(current_setting('c67.graph_a')::jsonb->>'schema_version','3','Graph is opt-in version three');
select is(jsonb_array_length(current_setting('c67.graph_a')::jsonb->'sources'),1,'One copied source');
select is(jsonb_array_length(current_setting('c67.graph_a')::jsonb->'days'),1,'One explicit initial day');
select is(jsonb_array_length(current_setting('c67.graph_a')::jsonb->'stops'),2,'Landing is not an extra visit');
select is(jsonb_array_length(current_setting('c67.graph_a')::jsonb->'legs'),3,'Access, landing transfer and between-stop legs all survive');
select is(current_setting('c67.graph_a')::jsonb->'legs'->0->>'kind','access','First segment is origin to landing');
select is(current_setting('c67.graph_a')::jsonb->'legs'->1->>'kind','landing_to_first','Separate landing-to-first segment is explicit');
select is(current_setting('c67.graph_a')::jsonb->'legs'->2->>'kind','between_stops','Following-stop segment remains separate');
select is(current_setting('c67.graph_a')::jsonb->'legs'->1->>'duration_seconds','90','Creator transfer duration retains provenance');
select ok(current_setting('c67.graph_a')::jsonb->'legs'->0->>'duration_seconds' is null,'Unknown access duration is not zero');
select is(current_setting('c67.graph_a')::jsonb->'warnings','["leg_duration_unknown"]'::jsonb,'Unknown duration remains visible');
select isnt(current_setting('c67.graph_a')::jsonb->'stops'->0->>'id',current_setting('c67.graph_a')::jsonb->'stops'->0->>'source_stop_id','Trip stop is a separate occurrence identity');
select is(public.get_trip_graph(current_setting('c67.graph_a_id')::uuid),current_setting('c67.graph_a')::jsonb,'Whole graph reload is consistent');
select is(public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T09:00+07','UTC','departure_origin','51111111-1111-4111-8111-111111111111','{"longitude":0,"latitude":0,"label":"Synthetic origin"}'),current_setting('c67.graph_a')::jsonb,'Equivalent instant/JSON retry preserves every occurrence ID');
select throws_ok($$select public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','departure_origin','51111111-1111-4111-8111-111111111111','{"latitude":0,"longitude":0.5}')$$,'PT409','Request ID reused with different input','Changed origin conflicts');
select throws_ok($$select public.create_trip_v2('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','51111111-1111-4111-8111-111111111111')$$,'PT409','Request ID reused with different input','V2 cannot adopt V3 command');
select set_config('c67.graph_first',public.create_trip_v3('91111111-1111-4111-8111-111111111112','2026-11-01T02:00Z','UTC','start_at_landing','51111111-1111-4111-8111-111111111112')::text,true);
select is(jsonb_array_length(current_setting('c67.graph_first')::jsonb->'legs'),1,'Landing equal to first stop adds no duplicate transfer');
select is(current_setting('c67.graph_first')::jsonb->'days'->0->'landing'->>'trip_stop_id',current_setting('c67.graph_first')::jsonb->'stops'->0->>'id','Landing points at the first occurrence explicitly');
select is(current_setting('c67.graph_first')::jsonb->'warnings','[]'::jsonb,'Known synthetic route has no invented uncertainty');
select set_config('c67.legacy',public.create_trip_v2('11111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','51111111-1111-4111-8111-111111111113')->>'id',true);
select is(public.get_trip_graph(current_setting('c67.legacy')::uuid)->'days'->0->'landing'->>'kind','unknown','Legacy source does not fabricate landing geometry');
select is(jsonb_array_length(public.get_trip_graph(current_setting('c67.legacy')::uuid)->'legs'),1,'Legacy adjacency is normalized without invented access');
select is((select count(*)::integer from jsonb_object_keys(public.get_trip_snapshot(current_setting('c67.graph_a_id')::uuid))),5,'V1 shape remains unchanged');
select is((select count(*)::integer from jsonb_object_keys(public.get_trip_snapshot_v2(current_setting('c67.graph_a_id')::uuid))),11,'V2 shape remains unchanged');
select throws_ok($$select public.create_trip_v3('11111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','departure_origin',gen_random_uuid(),'{"latitude":0,"longitude":0}')$$,'PT400','Departure origin requires an origin and explicit source landing','Unknown landing cannot accept departure-origin command');
select throws_ok($$select public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','departure_origin',gen_random_uuid())$$,'PT400','Departure origin requires an origin and explicit source landing','Origin required for departure basis');
select throws_ok($$select public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','start_at_landing',gen_random_uuid(),'{"latitude":0,"longitude":0}')$$,'PT400','Origin is only accepted for departure_origin','Unused origin is not retained');
select throws_ok($$select public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','departure_origin',gen_random_uuid(),'{"latitude":91,"longitude":0}')$$,'PT400','Invalid origin point','Invalid coordinates rejected');
select throws_ok($$select public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','guess',gen_random_uuid())$$,'PT400','Invalid start time basis','Unknown basis rejected');
select throws_ok($$insert into public.trip_days default values$$,'42501','permission denied for table trip_days','Direct normalized writes denied');
select set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
select is((select count(*)::integer from public.trip_sources),0,'Other account cannot read sources');
select is((select count(*)::integer from public.trip_days),0,'Other account cannot read days');
select is((select count(*)::integer from public.trip_stops),0,'Other account cannot read stops');
select is((select count(*)::integer from public.trip_legs),0,'Other account cannot read legs');
select throws_ok($$select public.get_trip_graph(current_setting('c67.graph_a_id')::uuid)$$,'PT404','Trip not found','Foreign graph is hidden');
select throws_ok($$select public.get_trip_graph('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee')$$,'PT404','Trip not found','Missing graph uses uniform 404');
select throws_ok($$select public.get_trip_graph(null)$$,'PT400','Trip ID is required','Null graph ID rejected');
select set_config('c67.graph_b',public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','departure_origin','51111111-1111-4111-8111-111111111111','{"latitude":0,"longitude":0,"label":"Synthetic origin"}')::text,true);
select isnt(current_setting('c67.graph_b')::jsonb->'stops'->0->>'id',current_setting('c67.graph_a')::jsonb->'stops'->0->>'id','Distinct copies get distinct occurrence IDs');
reset role;
select throws_ok($$update public.trip_stops set title='Bypass' where trip_id=current_setting('c67.graph_a_id')::uuid$$,'42501','Trip graph is immutable; use a graph command','Even privileged child updates cannot silently drift snapshot');
select throws_ok($$delete from public.trip_legs where trip_id=current_setting('c67.graph_a_id')::uuid$$,'42501','Trip graph is immutable; use a graph command','Child deletion requires a graph command');
select throws_ok($$update public.trips set starts_at='2026-12-01T02:00Z' where id=current_setting('c67.graph_a_id')::uuid$$,'PT409','Trip graph fields require a graph command','Root schedule cannot drift child day');
select set_config('c67.graph_build_trip',current_setting('c67.graph_a_id'),true);
select throws_ok($$insert into public.trip_stops(id,trip_id,day_id,source_id,source_stop_id,position,title) values(gen_random_uuid(),current_setting('c67.graph_a_id')::uuid,(current_setting('c67.graph_b')::jsonb->'days'->0->>'id')::uuid,(current_setting('c67.graph_a')::jsonb->'sources'->0->>'id')::uuid,gen_random_uuid(),9,'Cross day')$$,'23503',null,'Composite day FK rejects cross-trip child');
select throws_ok($$insert into public.trip_stops(id,trip_id,day_id,source_id,source_stop_id,position,title) values(gen_random_uuid(),current_setting('c67.graph_a_id')::uuid,(current_setting('c67.graph_a')::jsonb->'days'->0->>'id')::uuid,(current_setting('c67.graph_b')::jsonb->'sources'->0->>'id')::uuid,gen_random_uuid(),9,'Cross source')$$,'23503',null,'Composite source FK rejects cross-trip attribution');
select throws_ok($$insert into public.trip_legs(trip_id,day_id,position,kind,to_trip_stop_id,estimate_origin) values(current_setting('c67.graph_a_id')::uuid,(current_setting('c67.graph_a')::jsonb->'days'->0->>'id')::uuid,9,'landing_to_first',(current_setting('c67.graph_b')::jsonb->'stops'->0->>'id')::uuid,'unknown')$$,'23503',null,'Leg endpoints cannot cross aggregate');
select throws_ok($$insert into public.trip_legs(trip_id,day_id,position,kind,from_trip_stop_id,to_trip_stop_id,estimate_origin) values(current_setting('c67.graph_a_id')::uuid,(current_setting('c67.graph_a')::jsonb->'days'->0->>'id')::uuid,9,'between_stops',(current_setting('c67.graph_a')::jsonb->'stops'->1->>'id')::uuid,(current_setting('c67.graph_a')::jsonb->'stops'->0->>'id')::uuid,'unknown')$$,'23514','Leg must connect adjacent stops','Reverse adjacency is not silently accepted');
select set_config('c67.graph_build_trip','',true);
update public.rundown_versions set route_template=jsonb_set(jsonb_set(route_template,'{legs,0,duration_seconds}','90.0'),'{stop_details,0,visit_duration_seconds}','300.0') where id='91111111-1111-4111-8111-111111111111';
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select is(public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','departure_origin','51111111-1111-4111-8111-111111111119','{"latitude":0,"longitude":0}')->'legs'->1->>'duration_seconds','90','Integral JSON decimal leg duration is supported');
select is(public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','departure_origin','51111111-1111-4111-8111-111111111119','{"latitude":0,"longitude":0}')->'stops'->0->>'visit_duration_seconds','300','Integral JSON decimal visit duration is supported');
select throws_ok($$update public.rundown_versions set route_template=jsonb_set(route_template,'{legs,0,duration_seconds}','90.5') where id='91111111-1111-4111-8111-111111111111'$$,'23514','Invalid leg duration','Fractional leg duration is rejected');
select throws_ok($$update public.rundown_versions set route_template='{"landing":{"kind":"separate","location":{"latitude":999,"longitude":0}}}' where id='91111111-1111-4111-8111-111111111111'$$,'23514','Invalid separate landing','Malformed source point rejected');
select throws_ok($$update public.rundown_versions set route_template='{"stop_details":[{"source_stop_id":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee"}]}' where id='91111111-1111-4111-8111-111111111111'$$,'23514','Invalid stop detail identity','Unknown source detail cannot enter copy');
select throws_ok($$update public.rundown_versions set route_template='{"legs":[{"id":"81111111-1111-4111-8111-111111111111","kind":"between_stops","from_stop_id":"21111111-1111-4111-8111-111111111112","to_stop_id":"21111111-1111-4111-8111-111111111111"}]}' where id='91111111-1111-4111-8111-111111111111'$$,'23514','Invalid adjacent-stop endpoints','Source edge must match adjacency');
select throws_ok($$update public.rundown_versions set route_template='{"stop_details":[{"source_stop_id":"21111111-1111-4111-8111-111111111111","visit_duration_seconds":-1}]}' where id='91111111-1111-4111-8111-111111111111'$$,'23514','Invalid visit duration','Negative source duration rejected');
update public.rundown_versions set route_template=null,title='Changed source' where id='91111111-1111-4111-8111-111111111111';
set local role authenticated;
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select is(public.get_trip_graph(current_setting('c67.graph_a_id')::uuid),current_setting('c67.graph_a')::jsonb,'Source changes do not replace a saved graph');
reset role;
set constraints all immediate;
delete from auth.users where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
select is((select count(*)::integer from public.trip_stops where trip_id=current_setting('c67.graph_a_id')::uuid),0,'Owner cleanup cascades through guarded graph');
select * from finish();
rollback;
